package com.himeros.recommendation;import com.himeros.shared.CurrentUser;import jakarta.validation.constraints.*;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/v1/discovery")public class RecommendationController{private final RecommendationService service;private final CurrentUser current;public RecommendationController(RecommendationService s,CurrentUser c){service=s;current=c;}@GetMapping List<RecommendationService.Recommendation> discover(@RequestParam(defaultValue="20")@Min(1)@Max(100)int limit){return service.discover(current.id(),limit);}}
